pub fn parse_fluentd_proxy(content: &str) -> Option<String> {
    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') || trimmed.starts_with(';') {
            continue;
        }

        // systemd Environment format
        if trimmed.starts_with("Environment=") {
            let env_part = trimmed.strip_prefix("Environment=").unwrap_or("").trim();
            let unquoted = env_part.trim_matches('"').trim_matches('\'');
            for item in unquoted.split_whitespace() {
                if let Some((k, v)) = item.split_once('=') {
                    let k_low = k.to_lowercase();
                    if k_low == "fluentd_http_proxy"
                        || k_low == "td_agent_http_proxy"
                        || k_low == "http_proxy"
                        || k_low == "https_proxy"
                        || k_low == "all_proxy"
                    {
                        let val = v.trim_matches('"').trim_matches('\'').trim();
                        if !val.is_empty() {
                            return Some(if val.starts_with("http://")
                                || val.starts_with("https://")
                                || val.starts_with("socks")
                            {
                                val.to_string()
                            } else {
                                format!("http://{}", val)
                            });
                        }
                    }
                }
            }
        }

        // Shell env assignment e.g. /etc/default/fluentd
        if let Some((k, v)) = trimmed.split_once('=') {
            let k_low = k.trim().to_lowercase();
            if k_low == "fluentd_http_proxy"
                || k_low == "td_agent_http_proxy"
                || k_low == "http_proxy"
                || k_low == "https_proxy"
                || k_low == "all_proxy"
            {
                let val = v.trim().trim_matches('"').trim_matches('\'').trim();
                if !val.is_empty() {
                    return Some(if val.starts_with("http://")
                        || val.starts_with("https://")
                        || val.starts_with("socks")
                    {
                        val.to_string()
                    } else {
                        format!("http://{}", val)
                    });
                }
            }
        }

        // Direct directive: http_proxy http://127.0.0.1:7890 or http_proxy "http://127.0.0.1:7890" or http_proxy = ...
        let mut parts = trimmed.split_whitespace();
        if let Some(first) = parts.next() {
            let first_clean = first.trim_end_matches(':').to_lowercase();
            if first_clean == "http_proxy" {
                let rest = trimmed[first.len()..]
                    .trim()
                    .trim_start_matches('=')
                    .trim()
                    .trim_matches('"')
                    .trim_matches('\'');
                if !rest.is_empty()
                    && (rest.starts_with("http://")
                        || rest.starts_with("https://")
                        || rest.starts_with("socks")
                        || rest.contains(':'))
                {
                    return Some(if rest.starts_with("http://")
                        || rest.starts_with("https://")
                        || rest.starts_with("socks")
                    {
                        rest.to_string()
                    } else {
                        format!("http://{}", rest)
                    });
                }
            }
        }

        if let Some((k, v)) = trimmed.split_once(':') {
            let k_low = k.trim().trim_matches('"').trim_matches('\'').to_lowercase();
            if k_low == "http_proxy" {
                let val = v.trim().trim_matches('"').trim_matches('\'').trim();
                if !val.is_empty()
                    && (val.starts_with("http://")
                        || val.starts_with("https://")
                        || val.starts_with("socks")
                        || val.contains(':'))
                {
                    return Some(if val.starts_with("http://")
                        || val.starts_with("https://")
                        || val.starts_with("socks")
                    {
                        val.to_string()
                    } else {
                        format!("http://{}", val)
                    });
                }
            }
        }
    }

    None
}

