pub fn parse_tor_proxy(content: &str) -> Option<String> {
    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty()
            || trimmed.starts_with('#')
            || trimmed.starts_with(';')
            || trimmed.starts_with("//")
        {
            continue;
        }

        // systemd Environment format
        if trimmed.starts_with("Environment=") {
            let env_part = trimmed.strip_prefix("Environment=").unwrap_or("").trim();
            let unquoted = env_part.trim_matches('"').trim_matches('\'');
            for item in unquoted.split_whitespace() {
                if let Some((k, v)) = item.split_once('=') {
                    let k_low = k.to_lowercase();
                    if k_low == "tor_http_proxy"
                        || k_low == "tor_https_proxy"
                        || k_low == "http_proxy"
                        || k_low == "https_proxy"
                        || k_low == "upstream_proxy"
                        || k_low == "all_proxy"
                    {
                        let val = v.trim_matches('"').trim_matches('\'').trim();
                        if !val.is_empty() {
                            return Some(if val.starts_with("http://")
                                || val.starts_with("https://")
                                || val.starts_with("socks")
                            {
                                val.to_string()
                            } else {
                                format!("http://{}", val)
                            });
                        }
                    }
                }
            }
        }

        // Shell env assignment e.g. /etc/default/tor
        if let Some((k, v)) = trimmed.split_once('=') {
            let k_low = k.trim().to_lowercase();
            if k_low == "tor_http_proxy"
                || k_low == "tor_https_proxy"
                || k_low == "http_proxy"
                || k_low == "https_proxy"
                || k_low == "upstream_proxy"
                || k_low == "all_proxy"
            {
                let val = v.trim().trim_matches('"').trim_matches('\'').trim();
                if !val.is_empty()
                    && (val.starts_with("http://")
                        || val.starts_with("https://")
                        || val.starts_with("socks")
                        || val.contains(':'))
                {
                    return Some(if val.starts_with("http://")
                        || val.starts_with("https://")
                        || val.starts_with("socks")
                    {
                        val.to_string()
                    } else {
                        format!("http://{}", val)
                    });
                }
            }
        }

        // Tor torrc directives:
        // HTTPProxy 127.0.0.1:8080
        // HTTPSProxy 127.0.0.1:8080
        // Socks4Proxy 127.0.0.1:1080
        // Socks5Proxy 127.0.0.1:1080
        let parts: Vec<&str> = trimmed.split_whitespace().collect();
        if parts.len() >= 2 {
            let directive = parts[0].to_ascii_lowercase();
            let target = parts[1].trim_matches('"').trim_matches('\'');
            if !target.is_empty() {
                if directive == "httpproxy" || directive == "httpsproxy" {
                    return Some(if target.starts_with("http://") || target.starts_with("https://") || target.starts_with("socks") {
                        target.to_string()
                    } else {
                        format!("http://{}", target)
                    });
                } else if directive == "socks5proxy" {
                    return Some(if target.starts_with("socks") {
                        target.to_string()
                    } else {
                        format!("socks5://{}", target)
                    });
                } else if directive == "socks4proxy" {
                    return Some(if target.starts_with("socks") {
                        target.to_string()
                    } else {
                        format!("socks4://{}", target)
                    });
                }
            }
        }
    }

    None
}

pub fn get_tor_proxy() -> Option<(String, PathBuf)> {
    let paths = get_tor_config_paths();
    for p in paths {
        if let Ok(content) = std::fs::read_to_string(&p) {
            if let Some(proxy) = parse_tor_proxy(&content) {
                return Some((proxy, p));
            }
        }
    }
    if let Ok(val) = std::env::var("TOR_HTTP_PROXY") {
        let trim = val.trim();
        if !trim.is_empty() {
            let proxy = if trim.starts_with("http://")
                || trim.starts_with("https://")
                || trim.starts_with("socks")
            {
                trim.to_string()
            } else {
                format!("http://{}", trim)
            };
            return Some((proxy, PathBuf::from("env:TOR_HTTP_PROXY")));
        }
    }
    None
}

pub fn get_cloudflared_config_paths() -> Vec<PathBuf> {
    let mut paths = Vec::new();
    if let Ok(file) = std::env::var("TUNNEL_CONFIG") {
        let p = PathBuf::from(file.trim());
        if p.exists() {
            paths.push(p);
        }
    }
    if let Ok(file) = std::env::var("CLOUDFLARED_CONFIG_FILE") {
        let p = PathBuf::from(file.trim());
        if p.exists() && !paths.contains(&p) {
            paths.push(p);
        }
    }
    if let Ok(file) = std::env::var("CLOUDFLARED_CONF") {
        let p = PathBuf::from(file.trim());
        if p.exists() && !paths.contains(&p) {
            paths.push(p);
        }
    }
    if let Some(home) = dirs::home_dir() {
        let user_candidates = [
            home.join(".cloudflared").join("config.yml"),
            home.join(".cloudflared").join("config.yaml"),
            home.join(".config").join("cloudflared").join("config.yml"),
            home.join(".config").join("cloudflared").join("config.yaml"),
            home.join(".config").join("systemd").join("user").join("cloudflared.service.d").join("http-proxy.conf"),
        ];
        for p in user_candidates {
            if p.exists() && !paths.contains(&p) {
                paths.push(p);
            }
        }
    }
    let system_paths = [
        PathBuf::from("/etc/cloudflared/config.yml"),
        PathBuf::from("/etc/cloudflared/config.yaml"),
        PathBuf::from("/usr/local/etc/cloudflared/config.yml"),
        PathBuf::from("/usr/local/etc/cloudflared/config.yaml"),
        PathBuf::from("/opt/homebrew/etc/cloudflared/config.yml"),
        PathBuf::from("/opt/homebrew/etc/cloudflared/config.yaml"),
        PathBuf::from("/etc/default/cloudflared"),
        PathBuf::from("/etc/sysconfig/cloudflared"),
        PathBuf::from("/etc/systemd/system/cloudflared.service.d/http-proxy.conf"),
        PathBuf::from("/etc/systemd/system/cloudflared-update.service.d/http-proxy.conf"),
    ];
    for p in system_paths {
        if p.exists() && !paths.contains(&p) {
            paths.push(p);
        }
    }
    paths
}

