pub fn parse_leaf_proxy(content: &str) -> Option<String> {
    if let Ok(val) = serde_json::from_str::<serde_json::Value>(content) {
        if let Some(obj) = val.as_object() {
            for key in [
                "proxy",
                "outbound_proxy",
                "target_proxy",
                "http_proxy",
                "https_proxy",
                "all_proxy",
                "leaf_proxy",
            ] {
                if let Some(v) = obj.get(key) {
                    if let Some(s) = v.as_str() {
                        let trim = s.trim();
                        if !trim.is_empty() {
                            return Some(if trim.starts_with("http://")
                                || trim.starts_with("https://")
                                || trim.starts_with("socks")
                            {
                                trim.to_string()
                            } else {
                                format!("http://{}", trim)
                            });
                        }
                    }
                }
            }
        }
    }

    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty()
            || trimmed.starts_with('#')
            || trimmed.starts_with(';')
            || trimmed.starts_with("//")
        {
            continue;
        }

        if trimmed.starts_with("Environment=") {
            let env_part = trimmed.strip_prefix("Environment=").unwrap_or("").trim();
            let unquoted = env_part.trim_matches('"').trim_matches('\'');
            for item in unquoted.split_whitespace() {
                if let Some((k, v)) = item.split_once('=') {
                    let k_low = k.to_lowercase();
                    if k_low == "leaf_proxy"
                        || k_low == "leaf_http_proxy"
                        || k_low == "http_proxy"
                        || k_low == "https_proxy"
                        || k_low == "all_proxy"
                    {
                        let val = v.trim_matches('"').trim_matches('\'').trim();
                        if !val.is_empty() {
                            return Some(if val.starts_with("http://")
                                || val.starts_with("https://")
                                || val.starts_with("socks")
                            {
                                val.to_string()
                            } else {
                                format!("http://{}", val)
                            });
                        }
                    }
                }
            }
        }

        let pair = if let Some((k, v)) = trimmed.split_once('=') {
            Some((k, v))
        } else if let Some((k, v)) = trimmed.split_once(':') {
            Some((k, v))
        } else {
            None
        };
        if let Some((k, v)) = pair {
            let k_low = k.trim().to_lowercase();
            if k_low == "proxy"
                || k_low == "outbound_proxy"
                || k_low == "target_proxy"
                || k_low == "http_proxy"
                || k_low == "https_proxy"
                || k_low == "all_proxy"
                || k_low == "leaf_proxy"
                || k_low == "leaf_http_proxy"
                || k_low == "http"
            {
                let val = v.trim().trim_matches('"').trim_matches('\'').trim();
                if !val.is_empty()
                    && (val.starts_with("http://")
                        || val.starts_with("https://")
                        || val.starts_with("socks")
                        || val.contains(':'))
                {
                    return Some(if val.starts_with("http://")
                        || val.starts_with("https://")
                        || val.starts_with("socks")
                    {
                        val.to_string()
                    } else {
                        format!("http://{}", val)
                    });
                }
            }
        }
    }
    None
}

