pub fn parse_adguardhome_proxy(content: &str) -> Option<String> {
    if let Ok(val) = serde_json::from_str::<serde_json::Value>(content) {
        if let Some(obj) = val.as_object() {
            for key in [
                "http_proxy",
                "http-proxy",
                "proxy",
                "upstream_proxy",
                "all_proxy",
                "adguard_proxy",
                "socks5",
            ] {
                if let Some(v) = obj.get(key) {
                    if let Some(s) = v.as_str() {
                        let trim = s.trim();
                        if !trim.is_empty() {
                            return Some(if trim.starts_with("http://")
                                || trim.starts_with("https://")
                                || trim.starts_with("socks")
                            {
                                trim.to_string()
                            } else {
                                format!("http://{}", trim)
                            });
                        }
                    }
                }
            }
        }
    }

    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty()
            || trimmed.starts_with('#')
            || trimmed.starts_with(';')
            || trimmed.starts_with("//")
        {
            continue;
        }

        if trimmed.starts_with("Environment=") {
            let env_part = trimmed.strip_prefix("Environment=").unwrap_or("").trim();
            let unquoted = env_part.trim_matches('"').trim_matches('\'');
            for item in unquoted.split_whitespace() {
                if let Some((k, v)) = item.split_once('=') {
                    let k_low = k.to_lowercase();
                    if k_low == "adguard_proxy"
                        || k_low == "adguardhome_proxy"
                        || k_low == "all_proxy"
                        || k_low == "http_proxy"
                        || k_low == "https_proxy"
                    {
                        let val = v.trim_matches('"').trim_matches('\'').trim();
                        if !val.is_empty() {
                            return Some(if val.starts_with("http://")
                                || val.starts_with("https://")
                                || val.starts_with("socks")
                            {
                                val.to_string()
                            } else {
                                format!("http://{}", val)
                            });
                        }
                    }
                }
            }
        }

        let pair = if let Some((k, v)) = trimmed.split_once('=') {
            Some((k, v))
        } else if let Some((k, v)) = trimmed.split_once(':') {
            Some((k, v))
        } else {
            None
        };
        if let Some((k, v)) = pair {
            let k_low = k.trim().to_lowercase();
            if k_low == "http_proxy"
                || k_low == "http-proxy"
                || k_low == "https_proxy"
                || k_low == "proxy"
                || k_low == "upstream_proxy"
                || k_low == "upstream-proxy"
                || k_low == "all_proxy"
                || k_low == "adguard_proxy"
                || k_low == "adguardhome_proxy"
                || k_low == "socks5"
            {
                let val = v.trim().trim_end_matches(';').trim().trim_matches('"').trim_matches('\'').trim();
                if !val.is_empty()
                    && (val.starts_with("http://")
                        || val.starts_with("https://")
                        || val.starts_with("socks")
                        || val.contains(':'))
                {
                    return Some(if val.starts_with("http://")
                        || val.starts_with("https://")
                        || val.starts_with("socks")
                    {
                        val.to_string()
                    } else {
                        format!("http://{}", val)
                    });
                }
            }
        }
    }
    None
}

pub fn get_adguardhome_proxy() -> Option<(String, PathBuf)> {
    let paths = get_adguardhome_config_paths();
    for p in paths {
        if let Ok(content) = std::fs::read_to_string(&p) {
            if let Some(proxy) = parse_adguardhome_proxy(&content) {
                return Some((proxy, p));
            }
        }
    }
    if let Ok(val) = std::env::var("ADGUARDHOME_HTTP_PROXY") {
        let trim = val.trim();
        if !trim.is_empty() {
            let proxy = if trim.starts_with("http://")
                || trim.starts_with("https://")
                || trim.starts_with("socks")
            {
                trim.to_string()
            } else {
                format!("http://{}", trim)
            };
            return Some((proxy, PathBuf::from("env:ADGUARDHOME_HTTP_PROXY")));
        }
    }
    if let Ok(val) = std::env::var("ADGUARD_PROXY") {
        let trim = val.trim();
        if !trim.is_empty() {
            let proxy = if trim.starts_with("http://")
                || trim.starts_with("https://")
                || trim.starts_with("socks")
            {
                trim.to_string()
            } else {
                format!("http://{}", trim)
            };
            return Some((proxy, PathBuf::from("env:ADGUARD_PROXY")));
        }
    }
    None
}

pub fn get_dnscrypt_config_paths() -> Vec<PathBuf> {
    let mut paths = Vec::new();
    if let Ok(file) = std::env::var("DNSCRYPT_PROXY_CONFIG") {
        let p = PathBuf::from(file.trim());
        if p.exists() {
            paths.push(p);
        }
    }
    if let Ok(file) = std::env::var("DNSCRYPT_CONFIG") {
        let p = PathBuf::from(file.trim());
        if p.exists() && !paths.contains(&p) {
            paths.push(p);
        }
    }
    if let Some(home) = dirs::home_dir() {
        let user_candidates = [
            home.join(".config").join("dnscrypt-proxy").join("dnscrypt-proxy.toml"),
            home.join(".dnscrypt-proxy").join("dnscrypt-proxy.toml"),
            home.join(".config").join("dnscrypt-proxy.toml"),
            home.join(".dnscrypt-proxy.toml"),
            home.join(".config").join("systemd").join("user").join("dnscrypt-proxy.service.d").join("http-proxy.conf"),
        ];
        for p in user_candidates {
            if p.exists() && !paths.contains(&p) {
                paths.push(p);
            }
        }
    }
    let system_paths = [
        PathBuf::from("/etc/dnscrypt-proxy/dnscrypt-proxy.toml"),
        PathBuf::from("/etc/dnscrypt-proxy.toml"),
        PathBuf::from("/usr/local/etc/dnscrypt-proxy/dnscrypt-proxy.toml"),
        PathBuf::from("/usr/local/etc/dnscrypt-proxy.toml"),
        PathBuf::from("/opt/dnscrypt-proxy/dnscrypt-proxy.toml"),
        PathBuf::from("/etc/default/dnscrypt-proxy"),
        PathBuf::from("/etc/sysconfig/dnscrypt-proxy"),
        PathBuf::from("/etc/systemd/system/dnscrypt-proxy.service.d/http-proxy.conf"),
    ];
    for p in system_paths {
        if p.exists() && !paths.contains(&p) {
            paths.push(p);
        }
    }
    paths
}

pub fn get_dnscrypt_config_path() -> Option<PathBuf> {
    let paths = get_dnscrypt_config_paths();
    for p in &paths {
        if let Ok(content) = std::fs::read_to_string(p) {
            if parse_dnscrypt_proxy(&content).is_some() {
                return Some(p.clone());
            }
        }
    }
    paths.into_iter().next()
}

pub fn get_dnscrypt_write_path() -> PathBuf {
    if let Some(p) = get_dnscrypt_config_path() {
        return p;
    }
    if let Ok(file) = std::env::var("DNSCRYPT_PROXY_CONFIG") {
        return PathBuf::from(file.trim());
    }
    if let Ok(file) = std::env::var("DNSCRYPT_CONFIG") {
        return PathBuf::from(file.trim());
    }
    if let Some(home) = dirs::home_dir() {
        let dir = home.join(".config").join("dnscrypt-proxy");
        if dir.is_dir() {
            return dir.join("dnscrypt-proxy.toml");
        }
    }
    let etc_dir = PathBuf::from("/etc/dnscrypt-proxy");
    if etc_dir.is_dir() {
        return etc_dir.join("dnscrypt-proxy.toml");
    }
    let dropin_dir = PathBuf::from("/etc/systemd/system/dnscrypt-proxy.service.d");
    if dropin_dir.is_dir() {
        return dropin_dir.join("http-proxy.conf");
    }
    if let Some(home) = dirs::home_dir() {
        return home.join(".config").join("dnscrypt-proxy").join("dnscrypt-proxy.toml");
    }
    PathBuf::from("/etc/dnscrypt-proxy/dnscrypt-proxy.toml")
}

pub fn parse_dnscrypt_proxy(content: &str) -> Option<String> {
    if let Ok(val) = serde_json::from_str::<serde_json::Value>(content) {
        if let Some(obj) = val.as_object() {
            for key in [
                "http_proxy",
                "http-proxy",
                "proxy",
                "https_proxy",
                "all_proxy",
                "dnscrypt_proxy",
                "socks5",
            ] {
                if let Some(v) = obj.get(key) {
                    if let Some(s) = v.as_str() {
                        let trim = s.trim();
                        if !trim.is_empty() {
                            return Some(if trim.starts_with("http://")
                                || trim.starts_with("https://")
                                || trim.starts_with("socks")
                            {
                                trim.to_string()
                            } else {
                                format!("http://{}", trim)
                            });
                        }
                    }
                }
            }
        }
    }

    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') || trimmed.starts_with(';') {
            continue;
        }

        let lower = trimmed.to_ascii_lowercase();

        if lower.starts_with("environment=") {
            let env_part = trimmed["environment=".len()..]
                .trim()
                .trim_matches('"')
                .trim_matches('\'');
            if let Some((k, v)) = env_part.split_once('=') {
                let k_low = k.trim().to_ascii_lowercase();
                if k_low == "dnscrypt_proxy"
                    || k_low == "dnscrypt_http_proxy"
                    || k_low == "http_proxy"
                    || k_low == "https_proxy"
                    || k_low == "all_proxy"
                {
                    let val = v.trim().trim_matches('"').trim_matches('\'').trim();
                    if !val.is_empty() {
                        return Some(if val.starts_with("http://")
                            || val.starts_with("https://")
                            || val.starts_with("socks")
                        {
                            val.to_string()
                        } else {
                            format!("http://{}", val)
                        });
                    }
                }
            }
        }

        let pair = if let Some((k, v)) = trimmed.split_once('=') {
            Some((k, v))
        } else if let Some((k, v)) = trimmed.split_once(':') {
            Some((k, v))
        } else {
            None
        };
        if let Some((k, v)) = pair {
            let k_low = k.trim().to_lowercase();
            if k_low == "http_proxy"
                || k_low == "http-proxy"
                || k_low == "https_proxy"
                || k_low == "proxy"
                || k_low == "all_proxy"
                || k_low == "dnscrypt_proxy"
                || k_low == "dnscrypt_http_proxy"
                || k_low == "socks5"
            {
                let val = v.trim().trim_end_matches(';').trim().trim_matches('"').trim_matches('\'').trim();
                if !val.is_empty()
                    && (val.starts_with("http://")
                        || val.starts_with("https://")
                        || val.starts_with("socks")
                        || val.contains(':'))
                {
                    return Some(if val.starts_with("http://")
                        || val.starts_with("https://")
                        || val.starts_with("socks")
                    {
                        val.to_string()
                    } else {
                        format!("http://{}", val)
                    });
                }
            }
        }
    }
    None
}

