pub fn parse_unbound_proxy(content: &str) -> Option<String> {
    if let Ok(val) = serde_json::from_str::<serde_json::Value>(content) {
        if let Some(obj) = val.as_object() {
            for key in [
                "forward-addr",
                "forward_addr",
                "forward-host",
                "forward_host",
                "http_proxy",
                "http-proxy",
                "proxy",
                "https_proxy",
                "all_proxy",
                "unbound_proxy",
                "socks5",
            ] {
                if let Some(v) = obj.get(key) {
                    if let Some(s) = v.as_str() {
                        let trim = s.trim();
                        if !trim.is_empty() {
                            let clean = if let Some((h, p)) = trim.split_once('@') {
                                format!("{}:{}", h, p)
                            } else {
                                trim.to_string()
                            };
                            return Some(if clean.starts_with("http://")
                                || clean.starts_with("https://")
                                || clean.starts_with("socks")
                            {
                                clean
                            } else {
                                format!("http://{}", clean)
                            });
                        }
                    }
                }
            }
        }
    }

    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') || trimmed.starts_with(';') {
            continue;
        }

        let lower = trimmed.to_ascii_lowercase();

        if lower.starts_with("environment=") {
            let env_part = trimmed["environment=".len()..]
                .trim()
                .trim_matches('"')
                .trim_matches('\'');
            if let Some((k, v)) = env_part.split_once('=') {
                let k_low = k.trim().to_ascii_lowercase();
                if k_low == "unbound_proxy"
                    || k_low == "unbound_http_proxy"
                    || k_low == "http_proxy"
                    || k_low == "https_proxy"
                    || k_low == "all_proxy"
                {
                    let val = v.trim().trim_matches('"').trim_matches('\'').trim();
                    if !val.is_empty() {
                        return Some(if val.starts_with("http://")
                            || val.starts_with("https://")
                            || val.starts_with("socks")
                        {
                            val.to_string()
                        } else {
                            format!("http://{}", val)
                        });
                    }
                }
            }
        }

        let pair = if let Some((k, v)) = trimmed.split_once('=') {
            Some((k, v))
        } else if let Some((k, v)) = trimmed.split_once(':') {
            Some((k, v))
        } else {
            None
        };
        if let Some((k, v)) = pair {
            let k_low = k.trim().to_lowercase();
            if k_low == "forward-addr"
                || k_low == "forward_addr"
                || k_low == "forward-host"
                || k_low == "forward_host"
                || k_low == "http-proxy"
                || k_low == "http_proxy"
                || k_low == "https_proxy"
                || k_low == "proxy"
                || k_low == "all_proxy"
                || k_low == "unbound_proxy"
                || k_low == "socks5"
            {
                let val = v.trim().trim_end_matches(';').trim().trim_matches('"').trim_matches('\'').trim();
                if !val.is_empty()
                    && (val.starts_with("http://")
                        || val.starts_with("https://")
                        || val.starts_with("socks")
                        || val.contains(':')
                        || val.contains('@'))
                {
                    let clean = if let Some((h, p)) = val.split_once('@') {
                        format!("{}:{}", h, p)
                    } else {
                        val.to_string()
                    };
                    return Some(if clean.starts_with("http://")
                        || clean.starts_with("https://")
                        || clean.starts_with("socks")
                    {
                        clean
                    } else {
                        format!("http://{}", clean)
                    });
                }
            }
        }
    }
    None
}

