pub fn get_kresd_config_paths() -> Vec<PathBuf> {
    let mut paths = Vec::new();
    if let Ok(file) = std::env::var("KRESD_CONFIG") {
        let p = PathBuf::from(file.trim());
        if p.exists() {
            paths.push(p);
        }
    }
    if let Ok(file) = std::env::var("KRESD_CONF") {
        let p = PathBuf::from(file.trim());
        if p.exists() && !paths.contains(&p) {
            paths.push(p);
        }
    }
    if let Some(home) = dirs::home_dir() {
        let user_candidates = [
            home.join(".config").join("knot-resolver").join("kresd.conf"),
            home.join(".config").join("kresd").join("kresd.conf"),
            home.join(".kresd.conf"),
            home.join(".config").join("kresd.conf"),
            home.join(".config").join("systemd").join("user").join("kresd@.service.d").join("http-proxy.conf"),
            home.join(".config").join("systemd").join("user").join("kresd.service.d").join("http-proxy.conf"),
        ];
        for p in user_candidates {
            if p.exists() && !paths.contains(&p) {
                paths.push(p);
            }
        }
    }
    let system_paths = [
        PathBuf::from("/etc/knot-resolver/kresd.conf"),
        PathBuf::from("/etc/kresd/kresd.conf"),
        PathBuf::from("/etc/kresd.conf"),
        PathBuf::from("/usr/local/etc/knot-resolver/kresd.conf"),
        PathBuf::from("/opt/homebrew/etc/knot-resolver/kresd.conf"),
        PathBuf::from("/etc/default/kresd"),
        PathBuf::from("/etc/sysconfig/kresd"),
        PathBuf::from("/etc/systemd/system/kresd@.service.d/http-proxy.conf"),
        PathBuf::from("/etc/systemd/system/kresd.service.d/http-proxy.conf"),
    ];
    for p in system_paths {
        if p.exists() && !paths.contains(&p) {
            paths.push(p);
        }
    }
    paths
}

pub fn get_kresd_config_path() -> Option<PathBuf> {
    let paths = get_kresd_config_paths();
    for p in &paths {
        if let Ok(content) = std::fs::read_to_string(p) {
            if parse_kresd_proxy(&content).is_some() {
                return Some(p.clone());
            }
        }
    }
    paths.into_iter().next()
}

