pub fn parse_tmate_proxy(content: &str) -> Option<String> {
    if let Ok(val) = serde_json::from_str::<serde_json::Value>(content) {
        if let Some(obj) = val.as_object() {
            for key in [
                "proxy",
                "proxy_url",
                "proxyUrl",
                "http_proxy",
                "http-proxy",
                "httpProxy",
                "https_proxy",
                "tmate_proxy",
                "tmate-proxy",
                "tmate_http_proxy",
                "tunnel_proxy",
                "socks5_proxy",
                "socks_proxy",
            ] {
                if let Some(v) = obj.get(key) {
                    if let Some(s) = v.as_str() {
                        let trim = s.trim();
                        if !trim.is_empty() {
                            return Some(if trim.starts_with("http://")
                                || trim.starts_with("https://")
                                || trim.starts_with("socks")
                            {
                                trim.to_string()
                            } else {
                                format!("http://{}", trim)
                            });
                        }
                    }
                }
            }
        }
    }

    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }

        let lower = trimmed.to_ascii_lowercase();

        if lower.starts_with("environment=") {
            let env_part = trimmed["environment=".len()..]
                .trim()
                .trim_matches('"')
                .trim_matches('\'');
            if let Some((k, v)) = env_part.split_once('=') {
                let k_low = k.trim().to_ascii_lowercase();
                if k_low == "tmate_proxy"
                    || k_low == "tmate_http_proxy"
                    || k_low == "tunnel_proxy"
                    || k_low == "http_proxy"
                    || k_low == "https_proxy"
                    || k_low == "proxy_url"
                {
                    let val = v.trim().trim_matches('"').trim_matches('\'');
                    if !val.is_empty() {
                        return Some(if val.starts_with("http://")
                            || val.starts_with("https://")
                            || val.starts_with("socks")
                        {
                            val.to_string()
                        } else {
                            format!("http://{}", val)
                        });
                    }
                }
            }
        }

        if lower.starts_with('#') || lower.starts_with(';') || lower.starts_with("//") {
            continue;
        }

        // Handle tmux / tmate style config: `set -g tmate-proxy "http://..."` or `set-option -g tmate-proxy ...`
        if lower.starts_with("set ") || lower.starts_with("set-option ") {
            let tokens: Vec<&str> = trimmed.split_whitespace().collect();
            for (idx, &token) in tokens.iter().enumerate() {
                let tok_low = token.to_ascii_lowercase();
                if (tok_low == "tmate-proxy" || tok_low == "tmate_proxy" || tok_low == "proxy") && idx + 1 < tokens.len() {
                    let val = tokens[idx + 1].trim().trim_matches('"').trim_matches('\'');
                    if !val.is_empty() {
                        return Some(if val.starts_with("http://")
                            || val.starts_with("https://")
                            || val.starts_with("socks")
                        {
                            val.to_string()
                        } else {
                            format!("http://{}", val)
                        });
                    }
                }
            }
        }

        if lower.starts_with("export ") {
            let rest = &trimmed["export ".len()..].trim();
            if let Some((k, v)) = rest.split_once('=') {
                let k_low = k.trim().to_ascii_lowercase();
                if k_low == "tmate_proxy"
                    || k_low == "tmate_http_proxy"
                    || k_low == "tunnel_proxy"
                    || k_low == "http_proxy"
                    || k_low == "https_proxy"
                    || k_low == "all_proxy"
                {
                    let val = v.trim().trim_matches('"').trim_matches('\'');
                    if !val.is_empty() {
                        return Some(if val.starts_with("http://")
                            || val.starts_with("https://")
                            || val.starts_with("socks")
                        {
                            val.to_string()
                        } else {
                            format!("http://{}", val)
                        });
                    }
                }
            }
        }

        if let Some((k, v)) = trimmed.split_once(':') {
            let k_low = k.trim().to_ascii_lowercase();
            if k_low == "proxy"
                || k_low == "proxy_url"
                || k_low == "tmate_proxy"
                || k_low == "tmate-proxy"
                || k_low == "tmate_http_proxy"
                || k_low == "tunnel_proxy"
                || k_low == "http_proxy"
                || k_low == "https_proxy"
            {
                let val = v.trim().trim_matches('"').trim_matches('\'');
                if !val.is_empty() {
                    return Some(if val.starts_with("http://")
                        || val.starts_with("https://")
                        || val.starts_with("socks")
                    {
                        val.to_string()
                    } else {
                        format!("http://{}", val)
                    });
                }
            }
        }

        if let Some((k, v)) = trimmed.split_once('=') {
            let k_low = k.trim().to_ascii_lowercase();
            if k_low == "proxy"
                || k_low == "proxy_url"
                || k_low == "tmate_proxy"
                || k_low == "tmate-proxy"
                || k_low == "tmate_http_proxy"
                || k_low == "tunnel_proxy"
                || k_low == "http_proxy"
                || k_low == "https_proxy"
            {
                let val = v.trim().trim_matches('"').trim_matches('\'');
                if !val.is_empty() {
                    return Some(if val.starts_with("http://")
                        || val.starts_with("https://")
                        || val.starts_with("socks")
                    {
                        val.to_string()
                    } else {
                        format!("http://{}", val)
                    });
                }
            }
        }
    }

    None
}

